public class TransactionLogTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        try {
            FakeConnection ok = new FakeConnection();
            check("all statements succeed returns true",
                  true, TransactionLog.runAll(ok, new String[] {"a", "b"}));
            check("success log",
                  "[BEGIN, EXEC a, EXEC b, COMMIT]", ok.log.toString());

            FakeConnection bad = new FakeConnection();
            check("failing statement returns false",
                  false, TransactionLog.runAll(bad, new String[] {"a", "BAD", "c"}));
            check("failure log rolls back and stops",
                  "[BEGIN, EXEC a, ROLLBACK]", bad.log.toString());

            FakeConnection first = new FakeConnection();
            check("failure on the very first statement",
                  false, TransactionLog.runAll(first, new String[] {"BAD INSERT", "b"}));
            check("failure on first statement log",
                  "[BEGIN, ROLLBACK]", first.log.toString());

            FakeConnection none = new FakeConnection();
            check("empty statement array returns true",
                  true, TransactionLog.runAll(none, new String[] {}));
            check("empty transaction still commits",
                  "[BEGIN, COMMIT]", none.log.toString());
        } catch (RuntimeException e) {
            System.out.println("FAIL  unexpected exception -- the exception should be caught inside runAll, but got " + e);
            failures++;
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

