/**
 * Provided -- do not edit.
 *
 * FakeConnection stands in for a database connection. Every call appends a
 * line to its log so a test can see exactly what happened. execute THROWS
 * an IllegalStateException for any SQL containing "BAD", and a failed
 * execute logs nothing.
 */
class FakeConnection {
    final java.util.List<String> log = new java.util.ArrayList<>();

    void begin() {
        log.add("BEGIN");
    }

    void commit() {
        log.add("COMMIT");
    }

    void rollback() {
        log.add("ROLLBACK");
    }

    void execute(String sql) {
        if (sql.contains("BAD")) {
            throw new IllegalStateException("SQL error: " + sql);
        }
        log.add("EXEC " + sql);
    }
}

public class TransactionLog {

    public static boolean runAll(FakeConnection c, String[] statements) {
        c.begin();
        try {
            for (String sql : statements) {
                c.execute(sql);
            }
            c.commit();
            return true;
        } catch (RuntimeException e) {
            c.rollback();
            return false;
        }
    }
}
